using System.Linq;using UnityEngine;using UnityEditor;using Demo5.FrontEnd;
public static class InspectSettlementHud{public static string Run(){var c=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Settlement/SettlementScreen.prefab").GetComponent<SettlementController>();return string.Join("\n",c.Main.transform.Cast<Transform>().Select(t=>t.name+" "+((RectTransform)t).anchoredPosition+" "+((RectTransform)t).sizeDelta));}}
